#* {{quote-book|ru|year=1885|author=w:ru:Николай Лесков<t:{{w|Nikolai Leskov}}>|title=s:ru:[[Жемчужное_ожерелье_(Лесков)/ПСС_1902—1903_(ВТ:Ё)|Жемчужное ожерелье]]|chapter=Глава третья|location=|publisher=|newversion=English translation from|translator2=w:Richard Pevear and Larissa Volokhonsky|title2=The Pearl Necklace|location2=New York|publisher2=w:en:Alfred A. Knopf|year2=2013|page2=|pageurl2=
